{
  "candidates": [
    {
      "claimType": "conditionalAssociation",
      "statement": "晚间（20:00后）购买咖啡的行为与当晚入睡时间显著推迟（晚于00:40）存在强关联。",
      "supportingRefs": [
        "程序对齐",
        "财务"
      ],
      "alternativeExplanations": [
        "加班或工作压力导致既需要提神（买咖啡）又导致失眠，咖啡是结果而非原因。",
        "晚间购买咖啡的人本身就有熬夜习惯，两者由同一潜在因素驱动。"
      ],
      "verificationPlan": [
        {
          "op": "checkCoverage",
          "question": "检查所有工作日中，非晚间购买咖啡但入睡晚于00:40的案例，确认是否存在反例。"
        },
        {
          "op": "alignEvents",
          "question": "将加班记录与睡眠数据交叉比对，验证‘加班’是否比‘晚间购咖’更能预测晚睡。"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现大量晚间未购咖但依然晚睡的情况，或晚间购咖后次日白天补觉/精神尚可，则关联强度降低。",
      "evidenceGrade": "支持",
      "action": "observe"
    },
    {
      "claimType": "recurringBehavior",
      "statement": "该用户在特定日期（如09-19）有明确的‘睡前饮用咖啡’意图或行为模式。",
      "supportingRefs": [
        "财务"
      ],
      "alternativeExplanations": [
        "备注仅为当时的情绪宣泄或玩笑，实际并未饮用。",
        "用户可能购买了咖啡但未饮用，或留给他人饮用。"
      ],
      "verificationPlan": [
        {
          "op": "searchCounterEvidence",
          "question": "查询09-19当天的其他健康数据（如心率、活动量）是否有异常波动以佐证摄入兴奋剂。"
        },
        {
          "op": "retrieveRelated",
          "question": "回溯该用户历史订单中是否有类似‘睡前想喝’备注后的后续行为模式。"
        }
      ],
      "whatWouldChangeTheAnswer": "若能通过设备数据证实该时段生理唤醒水平升高，或找到同类备注下的确凿饮用证据，则命题成立。",
      "evidenceGrade": "线索",
      "action": "ask"
    }
  ]
}
